<?php

namespace Tests;

use Bbsnly\ChartJs\Chart;
use Bbsnly\ChartJs\Config\Data;
use Bbsnly\ChartJs\Config\Dataset;
use PHPUnit\Framework\TestCase;

/**
 * Executes the JavaScript generated by Chart::toHtml() in Node with a small
 * DOM/Chart.js stub, so the glue logic (canvas lookup, Chart construction,
 * instance registry, pagehide cleanup) is tested behaviorally instead of by
 * string matching. Skipped when Node is not installed.
 */
class JsOutputTest extends TestCase
{
    private static ?string $node = null;

    protected function setUp(): void
    {
        self::$node ??= self::findNode();

        if (self::$node === '') {
            if (getenv('GITHUB_ACTIONS') === 'true') {
                $this->fail('node must be available on GitHub Actions runners; refusing to silently skip JS tests in CI');
            }

            $this->markTestSkipped('node is required to test the generated JavaScript');
        }
    }

    /**
     * Find a node binary: explicit NODE_BINARY, then PATH, then the newest
     * nvm-managed install (nvm exposes node as a shell function, which PATH
     * lookups from PHP cannot see).
     */
    private static function findNode(): string
    {
        $candidates = [];

        $fromEnv = getenv('NODE_BINARY');
        if (is_string($fromEnv) && $fromEnv !== '') {
            $candidates[] = $fromEnv;
        }

        $lookup = PHP_OS_FAMILY === 'Windows' ? 'where node 2>NUL' : 'command -v node 2>/dev/null';
        $fromPath = shell_exec($lookup);
        if (is_string($fromPath) && trim($fromPath) !== '') {
            $lines = preg_split('/\R/', trim($fromPath));
            $candidates[] = is_array($lines) ? trim($lines[0]) : trim($fromPath);
        }

        $home = getenv('HOME');
        if (is_string($home) && $home !== '') {
            $nvmNodes = glob($home . '/.nvm/versions/node/*/bin/node');
            if (is_array($nvmNodes) && $nvmNodes !== []) {
                natsort($nvmNodes);
                $candidates[] = (string) end($nvmNodes);
            }
        }

        foreach ($candidates as $candidate) {
            if (is_executable($candidate)) {
                return $candidate;
            }
        }

        return '';
    }

    public function test_generated_js_constructs_chart_and_cleans_up(): void
    {
        $this->chartWithData();
        $result = $this->runHarness($this->chartWithData()->toHtml('js_test', false));

        $this->assertSame(['js_test'], $result['lookups']);
        $this->assertSame([], $result['errors']);
        $this->assertTrue($result['constructedWithCanvas']);
        $this->assertSame(['js_test'], $result['registry']);

        // pagehide with persisted=true (bfcache suspension) must keep the chart
        $this->assertFalse($result['destroyedAfterBfcacheHide']);
        $this->assertSame(['js_test'], $result['registryAfterBfcacheHide']);

        // pagehide with persisted=false (real navigation) must destroy and deregister
        $this->assertTrue($result['destroyedAfterNavigation']);
        $this->assertSame([], $result['registryAfterNavigation']);
    }

    /**
     * The config the browser receives must round-trip exactly to what
     * toJson() produced, even when the data needs aggressive escaping.
     */
    public function test_generated_js_passes_config_through_unchanged(): void
    {
        $chart = $this->chartWithData();
        $result = $this->runHarness($chart->toHtml('js_test', false));

        $this->assertSame(json_decode($chart->toJson(), true), $result['config']);
    }

    /**
     * Rendering the same verbatim id twice (a partial page swap) must
     * destroy the first instance before constructing the second, or
     * Chart.js refuses to reuse the canvas.
     */
    public function test_generated_js_rerender_destroys_previous_instance(): void
    {
        $result = $this->runHarness((new Chart)->toHtml('js_test', false), renders: 2);

        $this->assertSame(2, $result['constructedCount']);
        $this->assertSame(1, $result['destroyedDuringRender']);
        $this->assertSame(['js_test'], $result['registry']);
        $this->assertTrue($result['destroyedAfterNavigation']);
        $this->assertSame([], $result['registryAfterNavigation']);
    }

    public function test_generated_js_reports_missing_canvas(): void
    {
        $result = $this->runHarness((new Chart)->toHtml('js_test', false), canvasExists: false);

        $this->assertSame(['js_test'], $result['lookups']);
        $this->assertSame(0, $result['constructedCount']);
        $this->assertNull($result['registry']);
        $this->assertSame(['ChartJS-PHP: canvas element not found: js_test'], $result['errors']);
    }

    public function test_generated_js_has_valid_syntax(): void
    {
        $variants = [
            (new Chart)->toHtml('plain_chart'),
            (new Chart)->toHtml('verbatim-chart', false),
            $this->chartWithData()->toHtml('nasty-data-chart'),
        ];

        foreach ($variants as $html) {
            $file = $this->writeTempJs($this->scriptBody($html));

            try {
                exec(escapeshellarg(self::$node ?? '') . ' --check ' . escapeshellarg($file) . ' 2>&1', $output, $exitCode);
            } finally {
                unlink($file);
            }

            $this->assertSame(0, $exitCode, "node --check failed:\n" . implode("\n", $output));
        }
    }

    /**
     * A chart whose data exercises every character class that needs escaping
     * when embedded in an inline <script> block.
     */
    private function chartWithData(): Chart
    {
        $chart = new Chart;
        $chart->type = 'bar';

        $data = new Data;
        $data->datasets([
            (new Dataset)
                ->data([1, 2, 3])
                ->label('He said "hi" & <script></script> \\ \' 😀'),
        ]);
        $data->labels(['α', 'β', 'γ']);

        $chart->data($data);

        return $chart;
    }

    private function scriptBody(string $html): string
    {
        if (preg_match('/<script>(.*)<\/script>/s', $html, $matches) !== 1) {
            $this->fail('No <script> block found in toHtml() output');
        }

        return $matches[1];
    }

    /**
     * Run the script body between a browser-API stub and a probe that reports
     * what the script did as JSON on the last line of output.
     *
     * @return array<mixed>
     */
    private function runHarness(string $html, bool $canvasExists = true, int $renders = 1): array
    {
        $stub = <<<'JS'
        "use strict";
        const __calls = { lookups: [], constructed: [], destroyed: 0, listeners: {}, errors: [] };
        const __canvas = { tagName: "CANVAS" };
        const __canvasExists = %CANVAS_EXISTS%;
        const document = {
            getElementById(id) {
                __calls.lookups.push(id);
                return __canvasExists ? __canvas : null;
            }
        };
        const window = {
            addEventListener(type, handler) {
                (__calls.listeners[type] = __calls.listeners[type] || []).push(handler);
            }
        };
        const console = {
            error(...args) { __calls.errors.push(args.join(" ")); },
            log: globalThis.console.log.bind(globalThis.console)
        };
        class Chart {
            constructor(element, config) {
                __calls.constructed.push({ sameCanvas: element === __canvas, config });
            }
            destroy() { __calls.destroyed += 1; }
        }
        JS;

        $probe = <<<'JS'
        ;
        const __registryKeys = () => typeof window.bbsnlyChartJSInstances === "undefined"
            ? null
            : Object.keys(window.bbsnlyChartJSInstances);
        const __destroyedBefore = __calls.destroyed;
        const __result = {
            lookups: __calls.lookups,
            errors: __calls.errors,
            constructedCount: __calls.constructed.length,
            constructedWithCanvas: __calls.constructed.length >= 1 && __calls.constructed.every(c => c.sameCanvas),
            config: __calls.constructed.length >= 1 ? __calls.constructed[0].config : null,
            destroyedDuringRender: __destroyedBefore,
            registry: __registryKeys(),
            destroyedAfterBfcacheHide: null,
            registryAfterBfcacheHide: null,
            destroyedAfterNavigation: null,
            registryAfterNavigation: null
        };
        for (const handler of __calls.listeners["pagehide"] || []) handler({ persisted: true });
        __result.destroyedAfterBfcacheHide = __calls.destroyed > __destroyedBefore;
        __result.registryAfterBfcacheHide = __registryKeys();
        for (const handler of __calls.listeners["pagehide"] || []) handler({ persisted: false });
        __result.destroyedAfterNavigation = __calls.destroyed > __destroyedBefore;
        __result.registryAfterNavigation = __registryKeys();
        console.log(JSON.stringify(__result));
        JS;

        $body = $this->scriptBody($html);
        $renderedBodies = implode("\n;\n", array_fill(0, $renders, $body));

        $js = str_replace('%CANVAS_EXISTS%', $canvasExists ? 'true' : 'false', $stub)
            . "\n;\n" . $renderedBodies . "\n" . $probe;

        $file = $this->writeTempJs($js);

        try {
            exec(escapeshellarg(self::$node ?? '') . ' ' . escapeshellarg($file) . ' 2>&1', $output, $exitCode);
        } finally {
            unlink($file);
        }

        $this->assertSame(0, $exitCode, "node failed:\n" . implode("\n", $output));

        $decoded = json_decode((string) end($output), true);

        if (!is_array($decoded)) {
            $this->fail("Probe did not report JSON:\n" . implode("\n", $output));
        }

        return $decoded;
    }

    private function writeTempJs(string $js): string
    {
        $file = tempnam(sys_get_temp_dir(), 'chartjs_php_js_');

        if ($file === false) {
            $this->fail('Could not create a temporary file for the JS harness');
        }

        file_put_contents($file, $js);

        return $file;
    }
}
